function getTokenStemVariants(token) {
  const lower = String(token || '').toLowerCase().trim();
  if (!lower) return [];
  const variants = new Set([lower]);
  if (lower.endsWith('ies') && lower.length > 4) {
    variants.add(`${lower.slice(0, -3)}y`);
  } else if (lower.endsWith('y') && lower.length > 3 && !/[aeiou]y$/.test(lower)) {
    variants.add(`${lower.slice(0, -1)}ies`);
  }
  if (lower.endsWith('es') && lower.length > 4) {
    variants.add(lower.slice(0, -2));
    variants.add(lower.slice(0, -1));
  } else if (lower.endsWith('s') && !lower.endsWith('ss') && lower.length > 3) {
    variants.add(lower.slice(0, -1));
  } else if (lower.length >= 3 && !lower.endsWith('s')) {
    variants.add(`${lower}s`);
  }
  return Array.from(variants);
}

export function getAds({ category = 'all', query = '', network = 'all' } = {}) {
  let list = adsCatalog;
  if (category && category !== 'all') {
    list = list.filter(ad => ad.category === category || ad.category === 'all');
  }
  if (network && network !== 'all') {
    list = list.filter(ad => ad.network.toLowerCase() === network.toLowerCase());
  }
  if (query && query.trim()) {
    const normalizedQuery = query
      .toLowerCase()
      .replace(/[-_+]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const tokens = Array.from(
      new Set(
        normalizedQuery
          .replace(/[^\p{L}\p{N}\s]/gu, ' ')
          .split(/\s+/)
          .filter(Boolean)
      )
    );
    list = list.filter(ad => {
      const searchable = [
        ad.title,
        ad.desc,
        ad.sponsor,
        ad.cta,
        ad.url,
        ad.category,
        ad.network
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      if (searchable.includes(normalizedQuery)) return true;
      if (tokens.length === 0) return false;
      return tokens.every(token =>
        getTokenStemVariants(token).some(variant => searchable.includes(variant))
      );
    });
  }
  return list;
}

export function getAdById(id) {
  return adsCatalog.find(ad => String(ad.id) === String(id)) || null;
}

export function updateAd(id, payload) {
  const index = adsCatalog.findIndex(ad => String(ad.id) === String(id));
  if (index === -1) return null;
  const existing = adsCatalog[index];
  const updated = {
    ...existing,
    ...payload,
    id: existing.id
  };
  adsCatalog[index] = updated;
  return updated;
}

export function createAd(payload) {
  const id = payload.id || `custom-ad-${Date.now()}`;
  const newAd = {
    id,
    title: payload.title || 'Curated Discovery',
    desc: payload.desc || payload.description || '',
    img: payload.img || payload.thumbnailUrl || 'img/all_1.jpg',
    sponsor: payload.sponsor || payload.sellerName || 'Featured Partner',
    url: payload.url || '#',
    cta: payload.cta || 'Explore Free →',
    category: payload.category || 'all',
    network: payload.network || 'Partner',
    price: payload.price || 'Free'
  };
  adsCatalog.unshift(newAd);
  return newAd;
}
